(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  // 打开新建面板，确认难度选项与默认值
  const already = !!document.querySelector('.tb-diff');
  if (!already) [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.includes('新建项目'))?.click();
  await sleep(1000);
  return JSON.stringify({
    panelOpen: !!document.querySelector('.tb-card .tb-input'),
    diffOptions: [...document.querySelectorAll('.tb-diff-opt')].map((b) => b.textContent.trim()),
    defaultOn: document.querySelector('.tb-diff-opt-on')?.textContent.trim() || null,
  });
})()
